import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs['views'].get('camera')
    steer=1.8*h
    if cam and cam.get('walls'):
        sides=[[],[]]
        for b,d in cam['walls']:
            a=math.radians(b+h)
            s=-d*math.cos(a); y=d*math.sin(a)
            if s>0.2:
                sides[0 if y<0 else 1].append((s,y))
        def at(points,s):
            points=sorted(points)
            if not points:return None
            for p,q in zip(points,points[1:]):
                if p[0]<=s<=q[0]:
                    return p[1]+(q[1]-p[1])*(s-p[0])/max(.001,q[0]-p[0])
            p=min(points,key=lambda p:abs(p[0]-s))
            return p[1] if abs(p[0]-s)<1.5 else None
        L=4.0
        a=at(sides[0],L); b=at(sides[1],L)
        if a is not None and b is not None:
            y=(a+b)/2
            desired=math.degrees(math.atan2(5.2*y,L*L))
            steer=1.8*h-1.1*desired
    return (max(-34,min(34,steer)),-0.7,-23)

